const PRODUTOS = [];
let _id = 0;
const add = (cat, n, forma, tag, retro) => {
  const [a, b] = COR[n];
  const grupo = cat === "NBA" ? "nba" : (SELECOES.has(n) ? "sel" : "clube");
  const pre = cat === "NBA" ? "Regata NBA" : cat === "NFL" ? "Camisa NFL" : "Camisa";
  const nomePadrao = `${pre} ${n} - ${tag}`;
  const nome = NOMES[slug(nomePadrao)] || nomePadrao;
  PRODUTOS.push({ id: ++_id, key: slug(nomePadrao), cat, nome, tag, forma, retro, time: n, preco: PRECO, sigla: n.replace(/[^A-Za-zÀ-ú ]/g, "").split(" ").map(w => w[0]).join("").slice(0, 3).toUpperCase(),
    c1: "#" + (retro ? b : a), c2: "#" + (retro ? a : b), escudo: escudo(n, grupo) });
};
GRUPOS.forEach(([cat, lista, forma]) => parse(lista).forEach(([n]) => add(cat, n, forma, "Atual", false)));
add("Times do Mundo", "Chelsea", "camisa", "Atual II", false); // 2º uniforme do Chelsea
RETRO.forEach(n => add("Retrô", n, "camisa", "Retrô", true));

const TAMANHOS = ["P", "M", "G", "GG", "2XL", "3XL"]; // tamanhos disponíveis (Versão Fan)

// ---- UTILIDADES ----
const $ = (s) => document.querySelector(s);
const brl = (v) => v.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
const toast = (msg) => { const t = $("#toast"); t.textContent = msg; t.classList.add("on"); setTimeout(() => t.classList.remove("on"), 1800); };
function camisaSVG(p) {
  const tank = p.forma === "regata";
  const corpo = tank ? "M70 10 L70 60 L44 110 L44 196 L156 196 L156 110 L130 60 L130 10 C118 40 82 40 70 10Z"
                     : "M60 12 L20 38 L4 82 L36 96 L44 76 L44 196 L156 196 L156 76 L164 96 L196 82 L180 38 L140 12 C130 30 70 30 60 12Z";
  const detalhes = tank
    ? `<path d="M70 10 C82 40 118 40 130 10" fill="none" stroke="${p.c2}" stroke-width="6"/><path d="M44 110 L70 60 M156 110 L130 60" stroke="${p.c2}" stroke-width="5"/>`
    : `<path d="M60 12 C70 30 130 30 140 12" fill="none" stroke="${p.c2}" stroke-width="6"/><path d="M4 82 L36 96 M196 82 L164 96" stroke="${p.c2}" stroke-width="7"/>`;
  const faixa = p.retro ? `<rect x="44" y="120" width="112" height="12" fill="${p.c2}" opacity=".85"/><rect x="44" y="138" width="112" height="5" fill="${p.c2}" opacity=".6"/>` : `<rect x="44" y="150" width="112" height="46" fill="${p.c2}" opacity=".12"/>`;
  const num = tank || p.cat === "NFL" ? `<text x="100" y="125" text-anchor="middle" font-family="Montserrat,Arial" font-weight="800" font-size="46" fill="${p.c2}">${(p.id % 23) + 1}</text>` : `<text x="128" y="78" text-anchor="middle" font-family="Montserrat,Arial" font-weight="800" font-size="13" fill="${p.c2}">${p.sigla}</text>`;
  return `<svg viewBox="0 0 200 210" aria-hidden="true"><ellipse cx="100" cy="203" rx="62" ry="5" fill="#000" opacity=".1"/><path d="${corpo}" fill="${p.c1}" stroke="rgba(0,0,0,.3)" stroke-width="2" stroke-linejoin="round"/>${faixa}${detalhes}${num}</svg>`;
}

// ---- ESTADO ----
const norm = (s) => s.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase(); // busca sem acento
const PASSO = 24;                       // quantas camisas aparecem por vez ("Ver mais" mostra +24)
let filtro = "Todos";
let vis = PASSO;
const POR_ID = new Map(PRODUTOS.map(p => [p.id, p]));
const POR_KEY = new Map(PRODUTOS.map(p => [p.key, p]));
PRODUTOS.forEach(p => { p.fotos = fotosDe(p); p.busca = norm(`${p.nome} ${p.cat} ${p.time}`); });
const CATS = ["Todos", ...CATEGORIAS];
const CONTAGEM = {};
CATS.forEach(c => CONTAGEM[c] = c === "Todos" ? PRODUTOS.length : PRODUTOS.filter(p => p.cat === c).length);
const tamanhoEscolhido = {};
const fotoAtual = {};

// As fotos ficam embutidas em base64. Para o celular não carregar um HTML gigante a cada clique,
// cada foto vira um endereço curto (blob:) uma única vez e é reaproveitada em todo o site.
const _urls = new Map();
function urlFoto(s) {
  if (!s || s.slice(0, 5) !== "data:") return s;
  let u = _urls.get(s);
  if (u) return u;
  try {
    const bin = atob(s.slice(s.indexOf(",") + 1)), a = new Uint8Array(bin.length);
    for (let k = 0; k < bin.length; k++) a[k] = bin.charCodeAt(k);
    u = URL.createObjectURL(new Blob([a], { type: s.slice(5, s.indexOf(";")) }));
  } catch (e) { u = s; }
  _urls.set(s, u);
  return u;
}

// ---- CARRINHO (guardado no aparelho; cada item é identificado pelo "key" da camisa) ----
const CART_KEY = "ph-carrinho4";
let carrinho = [];
try {
  carrinho = (JSON.parse(localStorage.getItem(CART_KEY)) || []).filter(i => POR_KEY.has(i.k) && TAMANHOS.includes(i.tam) && i.qtd > 0);
} catch (e) { carrinho = []; }
const salvar = () => { try { localStorage.setItem(CART_KEY, JSON.stringify(carrinho)); } catch (e) {} };

// ---- LOJA ----
function renderChips() {
  const box = $("#chips");
  box.innerHTML = CATS.map(c => `<button type="button" class="chip ${c === filtro ? "on" : ""}" data-c="${c}" aria-pressed="${c === filtro}">${c}<span class="n">${CONTAGEM[c]}</span></button>`).join("");
  const on = box.querySelector(".on");
  if (on) box.scrollLeft = on.offsetLeft - (box.clientWidth - on.offsetWidth) / 2; // chip ativo fica à vista no celular
  document.querySelectorAll("#subnav [data-c]").forEach(a => {
    const ativo = a.dataset.c === filtro;
    a.classList.toggle("on", ativo);
    ativo ? a.setAttribute("aria-current", "true") : a.removeAttribute("aria-current");
  });
}

function listaAtual() {
  const termos = norm($("#search").value.trim()).split(/\s+/).filter(Boolean);
  const ordem = $("#sort").value;
  const l = PRODUTOS.filter(p => (filtro === "Todos" || p.cat === filtro) && termos.every(w => p.busca.includes(w)));
  l.sort((a, b) => (b.fotos.length > 0) - (a.fotos.length > 0)); // camisas com foto real aparecem primeiro (ordem estável)
  if (ordem) l.sort((a, b) => ordem === "asc" ? a.preco - b.preco : b.preco - a.preco);
  return l;
}

function cardHTML(p, antigo) {
  const fotos = p.fotos, tem = fotos.length > 0;
  const fi = Math.min(fotoAtual[p.id] || 0, fotos.length - 1);
  return `
    <article class="card">
      <div class="thumb ${tem ? "com-foto" : ""}${FOTO_BRANCA.has(p.key) ? " foto-branca" : ""}" ${tem ? `data-lb="${p.id}"` : ""}>
        ${p.tag === "Retrô" ? `<span class="tag">Retrô</span>` : ""}
        ${tem ? `<img class="foto" src="${urlFoto(fotos[fi])}" alt="${p.nome}" loading="lazy" decoding="async">` : camisaSVG(p)}
        ${p.escudo && !tem ? `<img class="badge" src="${urlFoto(p.escudo)}" alt="" loading="lazy">` : ""}
        ${tem ? `<span class="lupa">🔍 Ampliar</span>` : ""}
      </div>
      ${fotos.length > 1 ? `<div class="mini">${fotos.map((f, i) => `<button type="button" class="mini-b ${i === fi ? "on" : ""}" data-foto="${p.id}:${i}" aria-label="Foto ${i + 1}"><img src="${urlFoto(f)}" alt="" loading="lazy" decoding="async"></button>`).join("")}</div>` : ""}
      ${PORCENTAGEM_OFF > 0 ? `<div class="off">-${PORCENTAGEM_OFF}% OFF</div>` : ""}
      <div class="info">
        <h3>${p.nome}</h3>
        <small>${p.cat}</small>
        ${antigo ? `<s>${brl(antigo)}</s>` : ""}
        <div class="price">${brl(p.preco)} <span>no Pix</span></div>
        ${PARCELAS ? `<div class="parc">ou ${PARCELAS}x de ${brl(p.preco / PARCELAS)} sem juros</div>` : ""}
        <div class="sizes" role="group" aria-label="Tamanho">${TAMANHOS.map(t => `<button type="button" class="sz ${tamanhoEscolhido[p.id] === t ? "on" : ""}" data-id="${p.id}" data-t="${t}" aria-pressed="${tamanhoEscolhido[p.id] === t}">${t}</button>`).join("")}</div>
        <button type="button" class="medidas" data-medidas="1">📏 Tabela de medidas</button>
        <button type="button" class="btn" data-add="${p.id}">Adicionar ao carrinho</button>
      </div>
    </article>`;
}

function renderProdutos() {
  const l = listaAtual(), total = l.length;
  $("#resultado").textContent = total + (total === 1 ? " produto" : " produtos");
  $("#tituloLoja").textContent = filtro === "Todos" ? "Camisas de time" : filtro;
  $("#crumb").textContent = filtro === "Todos" ? "Início › Camisas" : `Início › Camisas › ${filtro}`;
  const antigo = PORCENTAGEM_OFF > 0 ? PRECO / (1 - PORCENTAGEM_OFF / 100) : 0;
  $("#grid").innerHTML = total
    ? l.slice(0, vis).map(p => cardHTML(p, antigo)).join("") + (total > vis ? `<button type="button" class="btn ghost more" data-more="1">Ver mais (${total - vis} restantes)</button>` : "")
    : `<div class="empty"><p>Nenhuma camisa encontrada.</p><button type="button" class="btn ghost" data-clear="1">Limpar busca e filtros</button></div>`;
}

// ---- FILTRO DE CATEGORIAS (Série A, Série B, NBA...): tudo via JavaScript, sem recarregar a página ----
const header = $(".header");
const telaPequena = matchMedia("(max-width:860px)");
let travaSub = 0;
function irParaLoja() {
  let desconto;
  if (telaPequena.matches) { travaSub = Date.now() + 900; header.classList.add("sub-off"); desconto = header.querySelector(".nav").offsetHeight + 8; }
  else desconto = header.offsetHeight + 8;
  const top = $("#loja").getBoundingClientRect().top + window.scrollY - desconto;
  window.scrollTo({ top: Math.max(0, top), behavior: "smooth" });
}
function filtrar(c, rolar) {
  filtro = c; vis = PASSO;
  renderChips(); renderProdutos();
  if (rolar) irParaLoja();
}
$("#chips").addEventListener("click", e => { const b = e.target.closest("[data-c]"); if (b) filtrar(b.dataset.c); });
$("#subnav").addEventListener("click", e => {
  const a = e.target.closest("a"); if (!a) return;
  if (a.dataset.md) { e.preventDefault(); abrirMd(); return; }
  if (a.dataset.c) { e.preventDefault(); filtrar(a.dataset.c, true); }
});
let _busca;
$("#search").addEventListener("input", () => { clearTimeout(_busca); _busca = setTimeout(() => { vis = PASSO; renderProdutos(); }, 120); });
$("#search").addEventListener("search", () => { vis = PASSO; renderProdutos(); });
$("#sort").addEventListener("change", () => { vis = PASSO; renderProdutos(); });

// No celular o menu de categorias some ao descer a página e volta ao subir (sobra mais espaço para as camisas)
let ultimoY = window.scrollY, _tick = false;
addEventListener("scroll", () => {
  if (_tick) return; _tick = true;
  requestAnimationFrame(() => {
    const y = window.scrollY, d = y - ultimoY;
    if (!telaPequena.matches || y < 60) header.classList.remove("sub-off");
    else if (Date.now() < travaSub || d > 6) header.classList.add("sub-off");
    else if (d < -6) header.classList.remove("sub-off");
    ultimoY = y; _tick = false;
  });
}, { passive: true });

// troca a foto do card sem refazer a lista inteira
function setFoto(id, i) {
  fotoAtual[id] = i;
  const p = POR_ID.get(id), th = document.querySelector(`#grid [data-lb="${id}"]`);
  if (!p || !th) return;
  const im = th.querySelector("img.foto"); if (im) im.src = urlFoto(p.fotos[i]);
  th.closest(".card").querySelectorAll(".mini-b").forEach((b, k) => b.classList.toggle("on", k === i));
}

$("#grid").addEventListener("click", e => {
  const t = e.target;
  const fb = t.closest("[data-foto]");
  if (fb) { const [id, i] = fb.dataset.foto.split(":"); setFoto(+id, +i); return; }
  const lbEl = t.closest("[data-lb]");
  if (lbEl) { abrirLb(+lbEl.dataset.lb); return; }
  const bt = t.closest("button"); if (!bt) return;
  if (bt.dataset.clear) { $("#search").value = ""; $("#sort").value = ""; filtrar("Todos"); return; }
  if (bt.dataset.medidas) { abrirMd(); return; }
  if (bt.dataset.more) { vis += PASSO; renderProdutos(); return; }
  if (bt.dataset.t) {
    tamanhoEscolhido[bt.dataset.id] = bt.dataset.t;
    bt.closest(".sizes").querySelectorAll(".sz").forEach(b => { const on = b === bt; b.classList.toggle("on", on); b.setAttribute("aria-pressed", on); });
    return;
  }
  if (bt.dataset.add) {
    const p = POR_ID.get(+bt.dataset.add), tam = tamanhoEscolhido[p.id];
    if (!tam) {
      const sz = bt.closest(".info").querySelector(".sizes");
      sz.classList.remove("falta"); void sz.offsetWidth; sz.classList.add("falta");
      toast("Escolha um tamanho"); return;
    }
    const item = carrinho.find(i => i.k === p.key && i.tam === tam);
    item ? item.qtd++ : carrinho.push({ k: p.key, tam, qtd: 1 });
    salvar(); renderCarrinho(); toast("Adicionado ao carrinho");
  }
});

// ---- CARRINHO ----
function renderCarrinho() {
  let total = 0, qtd = 0;
  $("#items").innerHTML = carrinho.length ? carrinho.map((i, idx) => {
    const p = POR_KEY.get(i.k); total += p.preco * i.qtd; qtd += i.qtd;
    return `<div class="line"><div><b>${p.nome}</b><br><small>Tamanho: ${i.tam}</small>
      <div class="qty"><button type="button" data-m="${idx}" aria-label="Diminuir">−</button><span>${i.qtd}</span><button type="button" data-p="${idx}" aria-label="Aumentar">+</button></div></div>
      <div style="text-align:right"><b>${brl(p.preco * i.qtd)}</b><br><button type="button" class="rm" data-r="${idx}">Remover</button></div></div>`;
  }).join("") : `<p class="empty">Seu carrinho está vazio.</p>`;
  $("#total").textContent = brl(total);
  $("#totalLabel").textContent = qtd ? `Total (${qtd} ${qtd === 1 ? "peça" : "peças"})` : "Total";
  $("#count").textContent = qtd;
}
$("#items").addEventListener("click", e => {
  const b = e.target.closest("button"); if (!b) return;
  const d = b.dataset;
  if (d.p !== undefined) carrinho[d.p].qtd++;
  if (d.m !== undefined) { carrinho[d.m].qtd--; if (carrinho[d.m].qtd <= 0) carrinho.splice(d.m, 1); }
  if (d.r !== undefined) carrinho.splice(d.r, 1);
  salvar(); renderCarrinho();
});
$("#clear").addEventListener("click", () => { carrinho = []; salvar(); renderCarrinho(); });
const abrir = (v) => {
  $("#drawer").classList.toggle("on", v); $("#overlay").classList.toggle("on", v);
  $("#drawer").setAttribute("aria-hidden", v ? "false" : "true");
  travar(); // trava a página de fundo enquanto o carrinho está aberto
};
$("#openCart").addEventListener("click", () => abrir(true));
$("#closeCart").addEventListener("click", () => abrir(false));
$("#overlay").addEventListener("click", () => abrir(false));
document.addEventListener("keydown", e => { if (e.key === "Escape" && $("#drawer").classList.contains("on")) abrir(false); });

// ---- PEDIDO PELO WHATSAPP (mensagem montada automaticamente com a lista e o total) ----
function montarMensagem() {
  let total = 0, pecas = 0;
  const linhas = carrinho.map((i, n) => {
    const p = POR_KEY.get(i.k), sub = p.preco * i.qtd;
    total += sub; pecas += i.qtd;
    return `*${n + 1}) ${p.nome}*\n    Tamanho: ${i.tam} | Qtd: ${i.qtd} | ${brl(p.preco)} un. = *${brl(sub)}*`;
  });
  const nome = $("#cliente").value.trim();
  return [
    "Olá, *PH IMPORTS*! 👋",
    "Quero fazer o seguinte pedido:",
    nome ? `\n👤 *Cliente:* ${nome}` : "",
    "\n🛒 *ITENS DO PEDIDO*",
    linhas.join("\n\n"),
    `\n📦 *Total de peças:* ${pecas}`,
    `💰 *TOTAL: ${brl(total)}* (no Pix)`,
    "\nPode confirmar a disponibilidade, o frete e a forma de pagamento? 🙏"
  ].filter(l => l !== "").join("\n");
}
$("#checkout").addEventListener("click", () => {
  if (!carrinho.length) { toast("Carrinho vazio"); return; }
  const url = `https://wa.me/${WHATSAPP}?text=${encodeURIComponent(montarMensagem())}`;
  const w = window.open(url, "_blank");
  if (!w) window.location.href = url; // se o navegador bloquear a nova aba, abre na mesma
});
try { $("#cliente").value = localStorage.getItem("ph-cliente") || ""; } catch (e) {}
$("#cliente").addEventListener("input", () => { try { localStorage.setItem("ph-cliente", $("#cliente").value); } catch (e) {} });

$("#emailBtn").addEventListener("click", () => {
  const form = $("#contactForm");
  if (!form.reportValidity()) return;
  const f = new FormData(form);
  const corpo = `Olá, PH IMPORTS! Sou ${f.get("nome")} (${f.get("email")}).\n\n${f.get("msg")}`;
  window.location.href = `mailto:${EMAIL}?subject=${encodeURIComponent("Contato pelo site - " + f.get("nome"))}&body=${encodeURIComponent(corpo)}`;
});
$("#contactForm").addEventListener("submit", e => {
  e.preventDefault();
  const f = new FormData(e.target);
  const msg = `Olá, PH IMPORTS! Sou ${f.get("nome")} (${f.get("email")}).\n\n${f.get("msg")}`;
  window.open(`https://wa.me/${WHATSAPP}?text=${encodeURIComponent(msg)}`, "_blank");
});

// ---- MENU E INÍCIO ----
$("#year").textContent = new Date().getFullYear();

// ---- TABELA DE MEDIDAS ----
const travar = () => document.body.classList.toggle("trava", $("#md").classList.contains("on") || $("#lb").classList.contains("on") || $("#drawer").classList.contains("on"));
function abrirMd() { $("#md").classList.add("on"); travar(); }
function fecharMd() { $("#md").classList.remove("on"); travar(); }
$("#mdX").addEventListener("click", fecharMd);
$("#md").addEventListener("click", e => { if (e.target.id === "md") fecharMd(); });
document.addEventListener("keydown", e => { if (e.key === "Escape") fecharMd(); });

// ---- GALERIA COM ZOOM (clique na foto) ----
let lbFotos = [], lbI = 0, lbZ = 1, lbTitulo = "", lbId = 0;
const lbImg = $("#lbImg"), lbStage = $("#lbStage");
function lbZoom(z) {
  lbZ = Math.max(1, Math.min(4, z));
  lbImg.style.transform = `scale(${lbZ})`;
  if (lbZ === 1) lbImg.style.transformOrigin = "50% 50%";
  lbImg.classList.toggle("zoomed", lbZ > 1);
  $("#lbPct").textContent = Math.round(lbZ * 100) + "%";
}
function lbRender() {
  lbImg.src = urlFoto(lbFotos[lbI]); lbImg.alt = lbTitulo; lbZoom(1);
  $("#lbTitle").textContent = lbTitulo + (lbFotos.length > 1 ? `  (${lbI + 1}/${lbFotos.length})` : "");
  $("#lbThumbs").innerHTML = lbFotos.length > 1 ? lbFotos.map((f, i) => `<button type="button" class="mini-b ${i === lbI ? "on" : ""}" data-i="${i}" aria-label="Foto ${i + 1}"><img src="${urlFoto(f)}" alt=""></button>`).join("") : "";
  $("#lbPrev").style.display = $("#lbNext").style.display = lbFotos.length > 1 ? "" : "none";
}
function abrirLb(id) {
  const p = POR_ID.get(id);
  lbId = id; lbFotos = p.fotos; lbI = Math.min(fotoAtual[id] || 0, lbFotos.length - 1); lbTitulo = p.nome;
  lbRender(); $("#lb").classList.add("on"); travar();
}
function fecharLb() {
  if (!$("#lb").classList.contains("on")) return;
  $("#lb").classList.remove("on"); travar();
  if (lbFotos.length) setFoto(lbId, lbI); // mantém no card a foto escolhida na galeria
}
const lbIr = (d) => { lbI = (lbI + d + lbFotos.length) % lbFotos.length; lbRender(); };
const lbOrigem = (cx, cy) => { // o zoom acompanha o mouse/dedo, como na Netshoes
  const s = lbStage.getBoundingClientRect();
  const x = Math.max(0, Math.min(100, (cx - s.left - lbImg.offsetLeft) / lbImg.offsetWidth * 100));
  const y = Math.max(0, Math.min(100, (cy - s.top - lbImg.offsetTop) / lbImg.offsetHeight * 100));
  lbImg.style.transformOrigin = `${x}% ${y}%`;
};
$("#lbX").addEventListener("click", fecharLb);
$("#lbPrev").addEventListener("click", () => lbIr(-1));
$("#lbNext").addEventListener("click", () => lbIr(1));
$("#lbPlus").addEventListener("click", () => lbZoom(lbZ + 0.75));
$("#lbMinus").addEventListener("click", () => lbZoom(lbZ - 0.75));
$("#lbThumbs").addEventListener("click", e => { const b = e.target.closest("[data-i]"); if (b) { lbI = +b.dataset.i; lbRender(); } });
lbStage.addEventListener("click", e => { if (e.target === lbStage) { fecharLb(); return; } if (lbZ === 1) { lbOrigem(e.clientX, e.clientY); lbZoom(2.5); } else lbZoom(1); });
lbStage.addEventListener("mousemove", e => { if (lbZ > 1) lbOrigem(e.clientX, e.clientY); });
lbStage.addEventListener("touchmove", e => { if (lbZ > 1) { e.preventDefault(); lbOrigem(e.touches[0].clientX, e.touches[0].clientY); } }, { passive: false });
// deslizar o dedo para o lado troca a foto (celular)
let _sx = 0, _sy = 0;
lbStage.addEventListener("touchstart", e => { _sx = e.touches[0].clientX; _sy = e.touches[0].clientY; }, { passive: true });
lbStage.addEventListener("touchend", e => {
  if (lbZ > 1 || lbFotos.length < 2) return;
  const t = e.changedTouches[0], dx = t.clientX - _sx, dy = t.clientY - _sy;
  if (Math.abs(dx) > 50 && Math.abs(dx) > Math.abs(dy) * 1.5) lbIr(dx < 0 ? 1 : -1);
}, { passive: true });
document.addEventListener("keydown", e => {
  if (!$("#lb").classList.contains("on")) return;
  if (e.key === "Escape") fecharLb();
  if (e.key === "ArrowLeft") lbIr(-1);
  if (e.key === "ArrowRight") lbIr(1);
  if (e.key === "+" || e.key === "=") lbZoom(lbZ + 0.75);
  if (e.key === "-") lbZoom(lbZ - 0.75);
});

// ---- MODO CLARO / ESCURO ----
let tema = "light";
try { tema = localStorage.getItem("ph-tema") || (matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light"); } catch (e) {}
const aplicarTema = (t) => { document.documentElement.dataset.tema = t; $("#tema").innerHTML = t === "dark" ? `<span class="ic">☀️</span><span class="tx"> Modo claro</span>` : `<span class="ic">🌙</span><span class="tx"> Modo escuro</span>`; };
aplicarTema(tema);
$("#tema").addEventListener("click", () => { tema = tema === "dark" ? "light" : "dark"; aplicarTema(tema); try { localStorage.setItem("ph-tema", tema); } catch (e) {} });

renderChips(); renderProdutos(); renderCarrinho();

// ---- CARROSSEL DO BANNER (clicável, automático, setas, bolinhas e deslizar) ----
(function () {
  const view = $("#bnView"), track = $("#bnTrack");
  if (!view || !track) return;
  const slides = [...track.children], n = slides.length;
  const INTERVALO = 5000; // tempo entre banners (ms)
  let i = 0, timer = null, x0 = 0, y0 = 0, dx = 0, drag = false, moveu = false;
  const dots = $("#bnDots");
  dots.innerHTML = slides.map((_, k) => `<button class="bn-dot" type="button" aria-label="Banner ${k + 1}" data-k="${k}"></button>`).join("");
  const ir = (k) => {
    i = (k + n) % n;
    track.style.transform = `translateX(${-i * 100}%)`;
    [...dots.children].forEach((d, j) => d.classList.toggle("on", j === i));
    slides.forEach((s, j) => s.setAttribute("aria-hidden", j === i ? "false" : "true"));
  };
  const parar = () => { clearInterval(timer); timer = null; };
  const iniciar = () => { parar(); if (n > 1 && !matchMedia("(prefers-reduced-motion: reduce)").matches) timer = setInterval(() => ir(i + 1), INTERVALO); };
  $("#bnPrev").addEventListener("click", () => { ir(i - 1); iniciar(); });
  $("#bnNext").addEventListener("click", () => { ir(i + 1); iniciar(); });
  dots.addEventListener("click", e => { const b = e.target.closest("[data-k]"); if (b) { ir(+b.dataset.k); iniciar(); } });
  view.addEventListener("mouseenter", parar);
  view.addEventListener("mouseleave", iniciar);
  document.addEventListener("visibilitychange", () => document.hidden ? parar() : iniciar());
  // deslizar com o dedo / arrastar com o mouse
  view.addEventListener("pointerdown", e => { if (e.target.closest(".bn-nav,.bn-dot")) return; drag = true; moveu = false; x0 = e.clientX; y0 = e.clientY; dx = 0; parar(); });
  view.addEventListener("pointermove", e => {
    if (!drag) return;
    dx = e.clientX - x0;
    if (Math.abs(dx) > 8 && Math.abs(dx) > Math.abs(e.clientY - y0)) {
      moveu = true; track.classList.add("drag");
      track.style.transform = `translateX(calc(${-i * 100}% + ${dx}px))`;
    }
  });
  const soltar = () => {
    if (!drag) return; drag = false; track.classList.remove("drag");
    if (moveu && Math.abs(dx) > view.offsetWidth * 0.12) ir(i + (dx < 0 ? 1 : -1)); else ir(i);
    iniciar();
  };
  view.addEventListener("pointerup", soltar);
  view.addEventListener("pointercancel", soltar);
  // se foi arrastar, não abre o link
  view.addEventListener("click", e => { if (moveu) { e.preventDefault(); e.stopPropagation(); moveu = false; } }, true);
  view.addEventListener("keydown", e => { if (e.key === "ArrowLeft") { ir(i - 1); iniciar(); } if (e.key === "ArrowRight") { ir(i + 1); iniciar(); } });
  ir(0); iniciar();
})();